<script setup lang="ts">
import {ref,computed,onMounted,watch,nextTick} from 'vue';import AppPage from '../AppPage.vue';import AppNavbar from '@/components/AppNavbar.vue';import AppButton from '@/components/AppButton.vue';import BaseCard from '@/components/BaseCard.vue';import SectionHeader from '@/components/SectionHeader.vue';import Stage1Status from './Stage1Status.vue';import Stage1Field from './Stage1Field.vue';import Stage1Region from './Stage1Region.vue';import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,label} from '../../services/stage1';import type {Data} from '../../services/stage1'
const props=defineProps<{query?:Data}>(),p=useStage1Page('point_'+(props.query?.id||'new')),{error,busy,loading,pending,dirty}=p,data=ref<Data|null>(null),form=ref<Data>({type:'COMMUNITY_PICKUP',opening:{weekdays:['1','2','3','4','5','6','7'],allDay:false,start:'09:00',end:'18:00',crossDay:false},reason:''}),disabled=computed(()=>busy.value||pending.value||!p.has('point.write'));let replacing=false
const weekdays=['周一','周二','周三','周四','周五','周六','周日'].map((label,index)=>({value:String(index+1),label}))
watch(form,()=>{if(!replacing)dirty.value=true},{deep:true})
function load(){return p.read(async()=>props.query?.id||data.value?.point.id?stage1Service.read<Data>('/points/'+(props.query?.id||data.value!.point.id)):null,v=>{replacing=true;data.value=v;if(v){form.value={...JSON.parse(JSON.stringify(v.point)),opening:{...v.point.opening,weekdays:v.point.opening?.weekdays.map(String)||[]},reason:''}}dirty.value=false;void nextTick(()=>{replacing=false})})}
async function save(){await p.write(()=>{const body:Data={};for(const key of ['type','name','provinceCode','cityCode','districtCode','address','contactName','phone','instructions','reason'])if(form.value[key]!==undefined)body[key]=form.value[key];const o=form.value.opening;body.opening={weekdays:o.weekdays.map(Number),allDay:o.allDay,crossDay:!o.allDay&&o.crossDay,...(!o.allDay?{start:o.start,end:o.end}:{})};if(form.value.coordinates)body.coordinates=form.value.coordinates;if(data.value)body.expectedVersion=data.value.point.version;return p.command<Data>(data.value?'/points/'+data.value.point.id:'/points',body,data.value?'PUT':'POST')},v=>{data.value={point:v,history:[]};dirty.value=false;return load()})}
onMounted(load)
</script>
<template><AppPage secondary :status="loading&&!data?'loading':'ready'"><template #navbar><AppNavbar title="履约点位" centered show-back/></template><view class="s1-point stack"><Stage1Status :error="error" :pending="pending" :busy="busy" @recover="p.recover(v=>{data={point:v,history:[]};load()})" @retry="p.retry(v=>{data={point:v,history:[]};load()})" @abandon="p.abandon(v=>{data={point:v,history:[]};load()})"/><BaseCard class="s1-form"><SectionHeader :title="data?'第 '+data.point.version+' 版':'新增点位'"/><Stage1Field v-model="form.type" label="点位类型" type="select" :options="[{value:'COMMUNITY_PICKUP',label:'社区自提'},{value:'STORE_REDEMPTION',label:'到店核销'}]" :disabled="disabled||!!data" required/><Stage1Field v-model="form.name" label="点位名称" :maximum="40" :disabled="disabled" required/><Stage1Region v-model="form" :disabled="disabled"/><Stage1Field v-model="form.address" label="详细地址" :maximum="200" :disabled="disabled" required/><Stage1Field v-model="form.contactName" label="联系人" :maximum="30" :disabled="disabled" required/><Stage1Field v-model="form.phone" label="联系电话" :maximum="20" :disabled="disabled" required/></BaseCard><BaseCard class="s1-form"><SectionHeader title="营业时段"/><Stage1Field v-model="form.opening.weekdays" label="营业日" type="multi" :options="weekdays" :disabled="disabled" required/><Stage1Field v-model="form.opening.allDay" label="全天营业" type="boolean" :disabled="disabled"/><template v-if="!form.opening.allDay"><Stage1Field v-model="form.opening.start" label="开始时间" hint="24小时制，例如09:00" :maximum="5" :disabled="disabled" required/><Stage1Field v-model="form.opening.end" label="结束时间" hint="24小时制，例如18:00" :maximum="5" :disabled="disabled" required/><Stage1Field v-model="form.opening.crossDay" label="结束时间为次日" type="boolean" :disabled="disabled"/></template><Stage1Field v-model="form.instructions" label="到达与服务说明" type="textarea" :maximum="500" :disabled="disabled"/><Stage1Field v-model="form.reason" label="变更原因" :maximum="500" :disabled="disabled" required/><AppButton v-if="p.has('point.write')" :disabled="pending" :loading="busy" @click="save">保存点位</AppButton></BaseCard><BaseCard v-if="data?.history.length" class="s1-form"><SectionHeader title="历史版本"/><view v-for="item in data.history" :key="item.version"><text>第 {{item.version}} 版 · {{item.at}}</text><text class="s1-copy">{{item.snapshot.name}} · {{label(item.snapshot.type)}} · {{item.snapshot.enabled?'启用':'停用'}}</text><text class="s1-copy">{{item.snapshot.address}} · {{item.snapshot.phone}}</text></view></BaseCard><AppButton variant="quiet" :loading="loading" @click="load">重新读取</AppButton></view></AppPage></template>
<style scoped lang="scss">.s1-point{padding:$space-4 $page-gutter}.s1-form{display:flex;flex-direction:column;gap:$space-4;font-size:15px;line-height:1.7;overflow-wrap:anywhere}.s1-copy{display:block;font-size:13px;color:$color-text-secondary}</style>
